-- docs/COURSE_CONTENT_CHECK_SPEC.md: the Day 8, 10 and 11 lesson examples used tables and columns that the
-- day's practice tables do not have. Replace each old SQL block with the new one in every institution's copy.
-- Content.payload is JSON text (newlines are the two characters \n). Each UPDATE matches only rows that still
-- hold the old block, so this is safe to run twice. Generated from the lesson files; checked by course-content-sql.test.ts.
UPDATE "contents" SET payload = replace(payload, 'SELECT d.dept_name,\n       COUNT(*)      AS headcount,      -- how many people\n       SUM(e.salary) AS total_salary,   -- add up all salaries\n       AVG(e.salary) AS avg_salary      -- average salary\nFROM employees e\nJOIN departments d ON d.dept_id = e.dept_id   -- link to the department name\nWHERE e.status = ''active''                     -- count only current workers\nGROUP BY d.dept_name                          -- one pile per department\nHAVING COUNT(*) > 3                           -- keep only piles with more than 3 people\nORDER BY total_salary DESC;                   -- biggest total first\n', 'SELECT d.name        AS department,\n       COUNT(*)      AS headcount,      -- how many people\n       SUM(e.salary) AS total_salary,   -- add up all salaries\n       AVG(e.salary) AS avg_salary      -- average salary\nFROM employees e\nJOIN departments d ON d.dept_id = e.dept_id   -- link to the department name\nWHERE e.status = ''active''                     -- count only current workers\nGROUP BY d.name                               -- one pile per department\nHAVING COUNT(*) > 3                           -- keep only piles with more than 3 people\nORDER BY total_salary DESC;                   -- biggest total first\n')
WHERE kind = 'md' AND strpos(payload, 'SELECT d.dept_name,\n       COUNT(*)      AS headcount,      -- how many people\n       SUM(e.salary) AS total_salary,   -- add up all salaries\n       AVG(e.salary) AS avg_salary      -- average salary\nFROM employees e\nJOIN departments d ON d.dept_id = e.dept_id   -- link to the department name\nWHERE e.status = ''active''                     -- count only current workers\nGROUP BY d.dept_name                          -- one pile per department\nHAVING COUNT(*) > 3                           -- keep only piles with more than 3 people\nORDER BY total_salary DESC;                   -- biggest total first\n') > 0;
UPDATE "contents" SET payload = replace(payload, 'WITH order_bands AS (                    -- step 1: name each order''s size\n  SELECT order_id, amount,\n         CASE WHEN amount < 5000  THEN ''Small''\n              WHEN amount <= 20000 THEN ''Medium''\n              ELSE ''Large'' END AS band   -- ELSE catches everything else\n  FROM sales_orders\n)\nSELECT band, COUNT(*) AS orders          -- step 2: count each band\nFROM order_bands\nGROUP BY band;\n', 'WITH order_bands AS (                    -- step 1: name each order''s size\n  SELECT order_id, amount,\n         CASE WHEN amount < 5000  THEN ''Small''\n              WHEN amount < 15000 THEN ''Medium''\n              ELSE ''Large'' END AS band   -- ELSE catches everything else\n  FROM orders\n)\nSELECT band, COUNT(*) AS orders          -- step 2: count each band\nFROM order_bands\nGROUP BY band;\n')
WHERE kind = 'md' AND strpos(payload, 'WITH order_bands AS (                    -- step 1: name each order''s size\n  SELECT order_id, amount,\n         CASE WHEN amount < 5000  THEN ''Small''\n              WHEN amount <= 20000 THEN ''Medium''\n              ELSE ''Large'' END AS band   -- ELSE catches everything else\n  FROM sales_orders\n)\nSELECT band, COUNT(*) AS orders          -- step 2: count each band\nFROM order_bands\nGROUP BY band;\n') > 0;
UPDATE "contents" SET payload = replace(payload, 'SELECT c.name, a.total_spend\nFROM (SELECT customer_id, SUM(amount) AS total_spend\n      FROM sales_orders GROUP BY customer_id) a   -- each customer''s total\nJOIN customers c ON c.customer_id = a.customer_id\nWHERE a.total_spend > (SELECT AVG(total_spend)     -- the subquery: the average\n                       FROM (SELECT SUM(amount) AS total_spend\n                             FROM sales_orders GROUP BY customer_id));\n', 'SELECT a.customer, a.total_spend\nFROM (SELECT customer, SUM(amount) AS total_spend\n      FROM orders GROUP BY customer) a             -- each customer''s total\nWHERE a.total_spend > (SELECT AVG(total_spend)     -- the subquery: the average\n                       FROM (SELECT SUM(amount) AS total_spend\n                             FROM orders GROUP BY customer))\nORDER BY a.total_spend DESC;\n')
WHERE kind = 'md' AND strpos(payload, 'SELECT c.name, a.total_spend\nFROM (SELECT customer_id, SUM(amount) AS total_spend\n      FROM sales_orders GROUP BY customer_id) a   -- each customer''s total\nJOIN customers c ON c.customer_id = a.customer_id\nWHERE a.total_spend > (SELECT AVG(total_spend)     -- the subquery: the average\n                       FROM (SELECT SUM(amount) AS total_spend\n                             FROM sales_orders GROUP BY customer_id));\n') > 0;
UPDATE "contents" SET payload = replace(payload, 'WITH monthly AS (                           -- step 1: revenue per product per month\n  SELECT branch,\n         strftime(''%Y-%m'', order_date) AS ym,   -- turn the date into \"2026-10\"\n         TRIM(UPPER(p.name))           AS product, -- clean the name\n         SUM(o.amount)                 AS revenue\n  FROM sales_orders o\n  JOIN products p ON p.product_id = o.product_id\n  GROUP BY branch, ym, product\n),\nranked AS (                                 -- step 2: rank inside each branch-month\n  SELECT *,\n         ROW_NUMBER() OVER (PARTITION BY branch, ym ORDER BY revenue DESC) AS rn\n  FROM monthly\n)\nSELECT branch, ym, product, revenue         -- step 3: keep only rank 1\nFROM ranked\nWHERE rn = 1;\n', 'WITH monthly AS (                           -- step 1: revenue per product per month\n  SELECT branch,\n         month            AS ym,                -- already \"2026-10\" in this table\n         TRIM(UPPER(product)) AS product,        -- clean the name: '' toor dal '' and ''TOOR DAL'' become one\n         SUM(revenue)     AS revenue\n  FROM sales\n  GROUP BY branch, ym, TRIM(UPPER(product))\n),\nranked AS (                                 -- step 2: rank inside each branch-month\n  SELECT *,\n         ROW_NUMBER() OVER (PARTITION BY branch, ym ORDER BY revenue DESC) AS rn\n  FROM monthly\n)\nSELECT branch, ym, product, revenue         -- step 3: keep only rank 1\nFROM ranked\nWHERE rn = 1;\n')
WHERE kind = 'md' AND strpos(payload, 'WITH monthly AS (                           -- step 1: revenue per product per month\n  SELECT branch,\n         strftime(''%Y-%m'', order_date) AS ym,   -- turn the date into \"2026-10\"\n         TRIM(UPPER(p.name))           AS product, -- clean the name\n         SUM(o.amount)                 AS revenue\n  FROM sales_orders o\n  JOIN products p ON p.product_id = o.product_id\n  GROUP BY branch, ym, product\n),\nranked AS (                                 -- step 2: rank inside each branch-month\n  SELECT *,\n         ROW_NUMBER() OVER (PARTITION BY branch, ym ORDER BY revenue DESC) AS rn\n  FROM monthly\n)\nSELECT branch, ym, product, revenue         -- step 3: keep only rank 1\nFROM ranked\nWHERE rn = 1;\n') > 0;
